package com.fintrack.controller; import com.fintrack.dto.GoalRequest; import com.fintrack.model.*; import com.fintrack.repository.GoalRepository; import com.fintrack.service.CurrentUser; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/goals") public class GoalController{private final GoalRepository repo;private final CurrentUser current;public GoalController(GoalRepository r,CurrentUser c){repo=r;current=c;}@GetMapping public List<Goal> all(Authentication a){return repo.findByUserId(current.get(a).getId());}@PostMapping public Goal add(@Valid @RequestBody GoalRequest r,Authentication a){Goal g=new Goal();g.setUser(current.get(a));g.setName(r.name());g.setCurrentAmount(r.currentAmount());g.setTargetAmount(r.targetAmount());g.setTargetDate(r.targetDate());return repo.save(g);}@PutMapping("/{id}")public Goal update(@PathVariable Long id,@Valid @RequestBody GoalRequest r,Authentication a){Goal g=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Goal not found"));if(!g.getUser().getId().equals(current.get(a).getId()))throw new IllegalArgumentException("Not your goal");g.setName(r.name());g.setCurrentAmount(r.currentAmount());g.setTargetAmount(r.targetAmount());g.setTargetDate(r.targetDate());return repo.save(g);}@DeleteMapping("/{id}")public void delete(@PathVariable Long id,Authentication a){Goal g=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Goal not found"));if(!g.getUser().getId().equals(current.get(a).getId()))throw new IllegalArgumentException("Not your goal");repo.delete(g);}}
